import numpy as np
def library(w):
    C=np.cos(w*t); S=np.sin(w*t)
    L={'1':np.ones_like(t),'x':x,'v':v,'x2':x**2,'x3':x**3,'xv':x*v,'x2v':x**2*v,'xv2':x*v**2,'v|v|':v*np.abs(v),'v2':v*v,'v3':v**3,'x4':x**4,
       'C':C,'S':S,'xC':x*C,'xS':x*S,'x2C':x**2*C,'x2S':x**2*S,'vC':v*C,'vS':v*S,'x3C':x**3*C,'x3S':x**3*S,'C2':np.cos(2*w*t),'S2':np.sin(2*w*t),'tC':t*C,'tS':t*S}
    return L
def greedy(w, n=9):
    L=library(w); keys=list(L.keys()); chosen=['1']
    while len(chosen)<n:
        best=None
        for k in keys:
            if k in chosen: continue
            X=np.column_stack([L[c] for c in chosen+[k]])
            cc,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
            e=np.mean((X@cc-dv_dt)**2)/np.var(dv_dt)
            if best is None or e<best[0]: best=(e,k)
        chosen.append(best[1])
    X=np.column_stack([L[c] for c in chosen]); cc,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
    return np.mean((X@cc-dv_dt)**2)/np.var(dv_dt), chosen, np.round(cc,4)
